import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;

interface ConnectionFactory {
    Connection createConnection() throws SQLException;
}

// Concrete implementation — swap for tests
class JdbcConnectionFactory implements ConnectionFactory {
    private final String url;
    private final String user;
    private final String password;

    public JdbcConnectionFactory(String url, String user, String password) {
        this.url = url;
        this.user = user;
        this.password = password;
    }

    @Override
    public Connection createConnection() throws SQLException {
        return DriverManager.getConnection(url, user, password);
    }
}

// In production you'd implement all ~40 Connection methods.
// For LLD, show the key `close()` method and hint at the rest.

class PooledConnection implements Connection {
    private final Connection delegate;
    private final ConnectionPool pool;
    private volatile boolean closed = false;

    public PooledConnection(Connection delegate, ConnectionPool pool) {
        this.delegate = delegate;
        this.pool = pool;
    }

    // ── The key method: close() returns to pool instead of closing ──
    @Override
    public void close() throws SQLException {
        if (closed) return;            // idempotent
        closed = true;
        pool.returnConnection(delegate);  // return the REAL connection
    }

    @Override
    public boolean isClosed() throws SQLException {
        return closed || delegate.isClosed();
    }

    // ── All other methods delegate to the real connection ──
    @Override
    public Statement createStatement() throws SQLException {
        checkOpen();
        return delegate.createStatement();
    }

    @Override
    public PreparedStatement prepareStatement(String sql) throws SQLException {
        checkOpen();
        return delegate.prepareStatement(sql);
    }

    @Override
    public void commit() throws SQLException {
        checkOpen();
        delegate.commit();
    }

    // ... ~35 more methods following the same pattern

    private void checkOpen() throws SQLException {
        if (closed)
            throw new SQLException("Connection already returned to pool");
    }
}

class ConnectionPool {
    private final ConnectionFactory factory;
    private final BlockingQueue<Connection> available;
    private final Set<Connection> allConnections =
        Collections.synchronizedSet(new HashSet<>());
    private final int poolSize;
    private volatile boolean closed = false;
    private static final int VALIDATION_TIMEOUT_SECONDS = 1;
    private static final int MAX_VALIDATION_RETRIES = 3;

    public ConnectionPool(ConnectionFactory factory, int poolSize)
            throws SQLException {
        if (poolSize <= 0)
            throw new IllegalArgumentException("poolSize must be positive");
        this.factory = factory;
        this.poolSize = poolSize;
        this.available = new LinkedBlockingQueue<>(poolSize);

        // Eagerly create all connections
        try {
            for (int i = 0; i < poolSize; i++) {
                Connection c = factory.createConnection();
                available.offer(c);
                allConnections.add(c);
            }
        } catch (SQLException e) {
            // Rollback: close any created connections
            closeAll();
            throw e;
        }
    }

    // ── borrow with timeout + validation ──
    public Connection borrowConnection(long timeoutMs)
            throws SQLException, InterruptedException {
        if (closed)
            throw new PoolClosedException("Pool is closed");

        long deadline = System.currentTimeMillis() + timeoutMs;

        for (int attempt = 0; attempt < MAX_VALIDATION_RETRIES; attempt++) {
            long remaining = deadline - System.currentTimeMillis();
            if (remaining <= 0)
                throw new PoolExhaustedException(
                    "Timeout waiting for connection");

            Connection conn = available.poll(remaining, TimeUnit.MILLISECONDS);
            if (conn == null)
                throw new PoolExhaustedException(
                    "Timeout waiting for connection");

            // Validate — if invalid, discard and create new
            if (isValid(conn)) {
                return new PooledConnection(conn, this);
            } else {
                // Dead connection — close it and try to create a replacement
                closeQuietly(conn);
                allConnections.remove(conn);
                try {
                    Connection fresh = factory.createConnection();
                    allConnections.add(fresh);
                    return new PooledConnection(fresh, this);
                } catch (SQLException e) {
                    // Replacement failed, try next iteration
                }
            }
        }
        throw new ConnectionValidationException(
            "Could not obtain a valid connection after " + MAX_VALIDATION_RETRIES + " attempts");
    }

    // ── return (called by PooledConnection.close()) ──
    public void returnConnection(Connection conn) {
        if (closed) {
            closeQuietly(conn);
            return;
        }
        if (!allConnections.contains(conn)) {
            // Not one of ours — caller bug, log and ignore
            return;
        }
        // Return to available queue — offer since size is bounded
        available.offer(conn);
    }

    // ── shutdown ─────────────────────────
    public void shutdown() {
        closed = true;
        closeAll();
    }

    // ── Validation ───────────────────────
    private boolean isValid(Connection conn) {
        try {
            return !conn.isClosed() && conn.isValid(VALIDATION_TIMEOUT_SECONDS);
        } catch (SQLException e) {
            return false;
        }
    }

    private void closeAll() {
        synchronized (allConnections) {
            for (Connection c : allConnections) {
                closeQuietly(c);
            }
            allConnections.clear();
        }
        available.clear();
    }

    private void closeQuietly(Connection c) {
        try { c.close(); } catch (SQLException ignored) {}
    }

    public int getIdleCount() { return available.size(); }
    public int getActiveCount() { return allConnections.size() - available.size(); }
}

ConnectionFactory factory = new JdbcConnectionFactory(
    "jdbc:postgresql://localhost/mydb", "user", "pass");
ConnectionPool pool = new ConnectionPool(factory, 10);

// Borrow with 5-second timeout
try (Connection conn = pool.borrowConnection(5000)) {
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT * FROM users WHERE id = ?")) {
        ps.setInt(1, 42);
        try (ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                System.out.println(rs.getString("name"));
            }
        }
    }
}  // conn.close() here → returns to pool, NOT closes underlying

// Clean shutdown
pool.shutdown();
